import casa_tool,numpy as np,mujoco
from scipy.spatial.transform import Rotation as R
from scipy.optimize import least_squares
s=casa_tool.Session('/app/instance.npz');m,d=s.model,s.data
A=np.load('/app/output/trajectory_verified_v18.npz')['actions']
for row in A[:-100]:s.step(row)
qa=np.array([m.joint('robot0_joint'+str(i)).qposadr[0] for i in range(1,8)])
ids=np.array([m.joint('robot0_joint'+str(i)).id for i in range(1,8)])
ranges=m.jnt_range[ids];eid=s.env.robots[0].eef_site_id['right']
nd=mujoco.MjData(m);nd.qpos[:]=d.qpos;q0=d.qpos[qa].copy();p0=d.site_xpos[eid].copy();O=d.site_xmat[eid].reshape(3,3).copy()
print('START',p0,q0,O,flush=True)

def solve(p,ori,start=q0):
 def fun(q):
  nd.qpos[qa]=q;mujoco.mj_forward(m,nd)
  return np.r_[(nd.site_xpos[eid]-p)*3,R.from_matrix(ori@nd.site_xmat[eid].reshape(3,3).T).as_rotvec(),.01*(q-start)]
 res=least_squares(fun,np.clip(start,ranges[:,0]+.03,ranges[:,1]-.03),bounds=(ranges[:,0]+.03,ranges[:,1]-.03),max_nfev=200)
 return res.x,np.linalg.norm(res.fun[:6])

results=[]
for angle in [20,40,60,80,100]:
 for xdelta in [-.02,0,.02,.05,.1]:
  goal=p0+np.array([xdelta,0,.16]);ori=R.from_euler('y',angle,degrees=True).as_matrix()@O
  q,e=solve(goal,ori)
  if e<.02:
   cs=[];minz=9;maxx=-9
   for t in np.linspace(0,1,70):
    nd.qpos[:]=d.qpos;nd.qpos[qa]=(1-t)*q0+t*q;mujoco.mj_forward(m,nd)
    p=nd.site_xpos[eid];minz=min(minz,p[2]);maxx=max(maxx,p[0]);
    for c in nd.contact:
     a=m.geom(c.geom1).name;b=m.geom(c.geom2).name
     if any(g.startswith(('robot0_','gripper0_')) for g in [a,b]):cs.append((a,b))
   cs=list(set(cs));results.append((len(cs),e,angle,xdelta,q.tolist(),minz,maxx,cs))
results.sort(key=lambda r:(r[0],r[1]))
for r in results:print('RESULT',r,flush=True)
np.savez('/app/output/retreat_ik.npz',q=np.array([r[4] for r in results]),params=np.array([[r[2],r[3]] for r in results]))
s.close()
PY
